import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in), 1 << 16);
    static StringTokenizer st = new StringTokenizer("");

    static long next() throws IOException {
        while (!st.hasMoreTokens()) st = new StringTokenizer(in.readLine());
        return Long.parseLong(st.nextToken());
    }

    public static void main(String[] args) throws IOException {
        int n = (int) next();
        ArrayDeque<Long> q = new ArrayDeque<>();  // completion times of the guest being checked and those waiting
        StringBuilder sb = new StringBuilder();
        for (int k = 0; k < n; k++) {
            long t = next();
            // checks finishing at or before t are done before this guest is considered
            while (!q.isEmpty() && q.peekFirst() <= t) q.pollFirst();
            int waiting = Math.max(0, q.size() - 1);
            long res;
            if (waiting > 10) {
                res = t;
            } else {
                res = (q.isEmpty() ? t : q.peekLast()) + 300;
                q.addLast(res);
            }
            if (k > 0) sb.append(' ');
            sb.append(res);
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int64 {
		sc.Scan()
		v, _ := strconv.ParseInt(sc.Text(), 10, 64)
		return v
	}
	n := int(next())
	q := []int64{} // completion times of the guest being checked and those waiting
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for k := 0; k < n; k++ {
		t := next()
		// checks finishing at or before t are done before this guest is considered
		for len(q) > 0 && q[0] <= t {
			q = q[1:]
		}
		waiting := max(0, len(q)-1)
		res := t
		if waiting <= 10 {
			if len(q) > 0 {
				res = q[len(q)-1] + 300
			} else {
				res = t + 300
			}
			q = append(q, res)
		}
		if k > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.FormatInt(res, 10))
	}
	w.WriteByte('\n')
}
